<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class GraduationController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$q=DB::table('graduation_records as gr')->join('students as s','s.id','=','gr.student_id')->join('study_groups as g','g.id','=','gr.study_group_id')->where('gr.academic_period_id',$p->id);if($r->filled('group_id'))$q->where('gr.study_group_id',$r->integer('group_id'));$rows=$q->select('gr.*','s.last_name','s.first_name','s.middle_name','g.name as group_name')->orderBy('g.name')->orderBy('s.last_name')->get();return view('graduation.index',compact('p','groups','rows'));}
 public function generate(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id']);$students=DB::table('students')->where(['current_group_id'=>$d['study_group_id'],'status'=>'active'])->pluck('id');foreach($students as $sid){$gia=DB::table('gia_student_results as gr')->join('gia_campaigns as c','c.id','=','gr.gia_campaign_id')->where(['c.academic_period_id'=>$p->id,'gr.student_id'=>$sid])->orderByDesc('gr.id')->select('gr.id')->first();DB::table('graduation_records')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$sid],['study_group_id'=>$d['study_group_id'],'gia_student_result_id'=>$gia->id??null,'created_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);}return back()->with('success','Реестр выпускников сформирован.');}
 public function check(Request $r,$id){$this->ok($r);$x=DB::table('graduation_records')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$issues=[];$gia=$x->gia_student_result_id?DB::table('gia_student_results')->find($x->gia_student_result_id):null;if(!$gia||!$gia->passed)$issues[]='Нет положительного результата ГИА';$debts=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where(['sh.academic_period_id'=>$x->academic_period_id,'a.student_id'=>$x->student_id])->whereRaw('a.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=a.attestation_sheet_id and a2.student_id=a.student_id)')->where('a.passed',0)->count();if($debts)$issues[]="Незакрытых задолженностей: $debts";DB::table('graduation_records')->where('id',$id)->update(['readiness'=>$issues?'blocked':'ready','readiness_issues'=>json_encode($issues,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);return back();}
 public function update(Request $r,$id){$this->ok($r);$x=DB::table('graduation_records')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);abort_unless($x->readiness==='ready',422,'Сначала устраните блокировки выпуска.');$d=$r->validate(['qualification'=>'required|string|max:255','gek_protocol_number'=>'nullable|string|max:100','gek_protocol_date'=>'nullable|date','diploma_series'=>'nullable|string|max:50','diploma_number'=>'nullable|string|max:100','registration_number'=>'nullable|string|max:100','issue_date'=>'nullable|date','honors'=>'required|in:no,yes']);DB::transaction(function()use($d,$id,$r){DB::table('graduation_records')->where('id',$id)->update($d+['status'=>'prepared','updated_at'=>now()]);$snap=DB::table('graduation_records')->find($id);DB::table('graduation_audit')->insert(['graduation_record_id'=>$id,'user_id'=>$r->user()->id,'action'=>'prepared','snapshot'=>json_encode($snap,JSON_UNESCAPED_UNICODE),'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Данные выпуска сохранены.');}
 public function document(Request $r,$id){$this->ok($r);$x=DB::table('graduation_records')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['document_type'=>'required|in:diploma,supplement,certificate,duplicate_diploma,duplicate_supplement','series'=>'nullable|string|max:50','number'=>'nullable|string|max:100','registration_number'=>'nullable|string|max:100','issued_on'=>'nullable|date','duplicate_reason'=>'nullable|string|max:500','note'=>'nullable|string|max:2000']);$dup=str_starts_with($d['document_type'],'duplicate_');DB::table('graduation_documents')->insert($d+['graduation_record_id'=>$id,'duplicate'=>$dup,'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('graduation_audit')->insert(['graduation_record_id'=>$id,'user_id'=>$r->user()->id,'action'=>$dup?'duplicate_registered':'document_registered','snapshot'=>json_encode($d,JSON_UNESCAPED_UNICODE),'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function receive(Request $r,$doc){$this->ok($r);$d=DB::table('graduation_documents as d')->join('graduation_records as g','g.id','=','d.graduation_record_id')->where('d.id',$doc)->select('d.*','g.academic_period_id')->first();PeriodGuard::writable($d->academic_period_id);$v=$r->validate(['received_by'=>'required|string|max:255']);DB::table('graduation_documents')->where('id',$doc)->update(['received_at'=>now(),'received_by'=>$v['received_by'],'updated_at'=>now()]);return back()->with('success','Выдача документа зарегистрирована.');}
 public function show(Request $r,$id){$this->ok($r);$x=DB::table('graduation_records as gr')->join('students as s','s.id','=','gr.student_id')->join('study_groups as g','g.id','=','gr.study_group_id')->where('gr.id',$id)->select('gr.*','s.last_name','s.first_name','s.middle_name','g.name as group_name')->first();abort_if(!$x,404);$docs=DB::table('graduation_documents')->where('graduation_record_id',$id)->orderByDesc('id')->get();$audit=DB::table('graduation_audit')->where('graduation_record_id',$id)->orderByDesc('id')->get();return view('graduation.show',compact('x','docs','audit'));}
 public function register(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('graduation_documents as d')->join('graduation_records as gr','gr.id','=','d.graduation_record_id')->join('students as s','s.id','=','gr.student_id')->where('gr.academic_period_id',$p->id)->select('d.*','s.last_name','s.first_name','s.middle_name')->orderBy('d.issued_on')->orderBy('d.id')->get();return view('graduation.register',compact('rows','p'));}
}